:root {
  --pixel-bg: #1a1c2c;
  --pixel-fg: #f4f4f4;
  --pixel-accent: #ffcd75;
  --pixel-shadow: #000;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--pixel-bg);
  color: var(--pixel-fg);
  font-family: "Courier New", monospace;
  image-rendering: pixelated;
}

.counter {
  background: #2a2e40;
  border: 4px solid var(--pixel-fg);
  box-shadow: 8px 8px 0 var(--pixel-shadow);
  padding: 2rem;
  text-align: center;
  width: min(90vw, 22rem);
}

.count {
  display: block;
  font-size: 5rem;
  line-height: 1;
  margin-bottom: 1.5rem;
  background: var(--pixel-bg);
  border: 4px solid var(--pixel-accent);
  padding: 0.5rem 0.25rem;
  color: var(--pixel-accent);
  text-shadow: 3px 3px 0 var(--pixel-shadow);
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font: inherit;
  font-weight: bold;
  padding: 0.75rem 1rem;
  min-width: 5.5rem;
  background: var(--pixel-fg);
  color: var(--pixel-bg);
  border: 4px solid var(--pixel-accent);
  box-shadow: 4px 4px 0 var(--pixel-shadow);
  cursor: pointer;
  text-transform: uppercase;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--pixel-shadow);
}

button:focus-visible {
  outline: 3px dashed var(--pixel-accent);
  outline-offset: 4px;
}

const count = document.getElementById('count');
const increase = document.getElementById('increase');
const decrease = document.getElementById('decrease');
const reset = document.getElementById('reset');

let value = 0;

function update() {
  count.textContent = value;
}

increase.addEventListener('click', () => {
  value += 1;
  update();
});

decrease.addEventListener('click', () => {
  value -= 1;
  update();
});

reset.addEventListener('click', () => {
  value = 0;
  update();
});

update();
